
UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
    "Transpose": {
        "Customer": "SELECT attribute, data FROM masters.customers, LATERAL (VALUES (''Customer ID'', CAST(icustomerid AS VARCHAR)), (''External Cust ID'', vcexternalcustid), (''Customer Name'', vccustomername), (''Customer Type'', vccustomertype), (''Verified Name'', vcverifiedname), (''Onboarding Date'', CAST(dtonboardingdate AS VARCHAR)), (''Email ID'', vcemail), (''Registered Mobile Number'', vcregisteredmobile), (''MCC'', CAST(imcc AS VARCHAR)), (''Country Code'', vccountrycode), (''Record Status'', CAST(irecordstatus AS VARCHAR)), (''Entry Date Time'', CAST(dtentrydatetime AS VARCHAR)), (''Last Modified'', CAST(lastmodified AS VARCHAR)), (''KYC'', vcattribs->>''kyc''), (''Risk'', vcattribs->>''risk''), (''Dealer ID'', vcattribs->>''dealer_id''), (''Gross Income'', vcattribs->>''gross_income''), (''Source Of Income'', vcattribs->>''source_of_income''), (''Termination Status'', vcattribs->>''termination_status''), (''Customer Onboarding Type'', vcattribs->>''customer_onboard_type''), (''Occupation'', vcattribs->>''occupation''), (''City'', vcattribs->>''city''), (''State'', vcattribs->>''state''), (''Account Type'', vcattribs->>''accountType''), (''Gender'', vcattribs->>''gender''), (''Account Sub Type'', vcattribs->>''accountSubType''), (''DOB'', vcattribs->>''doi_dob''), (''Mobile Num Update Time'', vcattribs->>''Mobile_no_UpdateTime''), (''Postal Code'', vcpostalcode), (''UCIC ID'', vcattribs->>''ucic_id''), (''Salutation'', vcsalutation), (''VC Gender'', vcgender), (''Birth Date'', CAST(dtdoidob AS VARCHAR)), (''Identity Type 1'', vcidentitytype1), (''Identity Detail 1'', vcidentitydetails1), (''Identity Type 2'', vcidentitytype2), (''Identity Detail 2'', vcidentitydetails2), (''Registered Address Geolocation'', vcregisteredaddressgeolocation)) AS t(attribute, data) WHERE itenantid = :tenantid :AttribsForm AND dtentrydatetime BETWEEN :StartDate AND :EndDate ORDER BY icustomerid DESC LIMIT :Load ;",
        "Account": "SELECT attribute, data FROM masters.accounts, LATERAL (VALUES (''Account ID'', CAST(iaccountid AS VARCHAR)), (''Customer ID'', CAST(icustomerid AS VARCHAR)), (''External Account ID'', vcexternalaccountid), (''Account Name'', vcaccountname), (''Account Type'',  CAST(iaccounttypeid AS VARCHAR)), (''IFSC'', vcifsc), (''Account Number'', vcaccount),(''Verified'', CAST(bverified AS VARCHAR)), (''MCC'', CAST(imcc AS VARCHAR)), (''Merchant'', CAST(bmerchant AS VARCHAR)), (''Record Status'', CAST(irecordstatus AS VARCHAR)), (''Entry Date Time'', CAST(dtentrydatetime AS VARCHAR)), (''Onboarding Date'', CAST(dtonboardingdate AS VARCHAR)),(''Last Modified'', CAST(lastmodified AS VARCHAR))) AS t(attribute, data) WHERE itenantid = :tenantid :AttribsForm AND dtentrydatetime BETWEEN :StartDate AND :EndDate ORDER BY iaccountid DESC LIMIT :Load ;",
        "VPA": "SELECT attribute, data FROM masters.vpa, LATERAL (VALUES (''VPA ID'', CAST(ivpaid AS VARCHAR)), (''Account ID'', CAST(iaccountid AS VARCHAR)), (''External VPA ID'', vcexternaladdressid), (''VPA'', vcaddress), (''Customer Name'', vcvpaname), (''Verified'', CAST(bverified AS VARCHAR)), (''MCC'', CAST(imcc AS VARCHAR)), (''Merchant'', CAST(bmerchant AS VARCHAR)), (''Record Status'', CAST(irecordstatus AS VARCHAR)), (''Entry Date Time'', CAST(dtentrydatetime AS VARCHAR)), (''Onboarding Date'', CAST(dtonboardingdate AS VARCHAR)), (''Product ID'', CAST(iproductid AS VARCHAR)), (''Expires On'', CAST(dtexpirydate AS VARCHAR)), (''Last Modified On'', CAST(lastmodified AS VARCHAR))) AS t(attribute, data) WHERE itenantid = :tenantid :AttribsForm AND dtentrydatetime BETWEEN :StartDate AND :EndDate ORDER BY ivpaid DESC LIMIT :Load ;"
    },
    "Normal": {
        "Customer": "SELECT icustomerid AS \\"Customer ID\\", vcexternalcustid AS \\"External Cust ID\\", vccustomername AS \\"Customer Name\\", vccustomertype AS \\"Customer Type\\", vcverifiedname AS \\"Verified Name\\", dtonboardingdate AS \\"Onboarding Date\\", vcemail AS \\"Email ID\\", vcregisteredmobile AS \\"Registered Mobile Number\\", imcc AS \\"MCC\\", vccountrycode AS \\"Country Code\\", irecordstatus AS \\"Record Status\\", dtentrydatetime AS \\"Entry Date Time\\", lastmodified AS \\"Last Modified\\", vcattribs->>''kyc'' AS \\"KYC\\", vcattribs->>''risk'' AS \\"Risk\\", vcattribs->>''dealer_id'' AS \\"Dealer ID\\", vcattribs->>''gross_income'' AS \\"Gross Income\\", vcattribs->>''source_of_income'' AS \\"Source Of Income\\", vcattribs->>''termination_status'' AS \\"Termination Status\\", vcattribs->>''customer_onboard_type'' AS \\"Customer Onboarding Type\\", vcattribs->>''occupation'' AS \\"Occupation\\", vcattribs->>''city'' AS \\"City\\", vcattribs->>''state'' AS \\"State\\", vcattribs->>''accountType'' AS \\"Account Type\\", vcattribs->>''gender'' AS \\"Gender\\", vcattribs->>''accountSubType'' AS \\"Account Sub Type\\", vcattribs->>''doi_dob'' AS \\"DOB\\", vcattribs->>''Mobile_no_UpdateTime'' AS \\"Mobile Num Update Time\\", vcpostalcode AS \\"Postal Code\\", vcattribs->>''ucic_id'' AS \\"UCIC ID\\", vcsalutation AS \\"Salutation\\", vcgender AS \\"VC Gender\\", dtdoidob AS \\"Birth Date\\", vcidentitytype1 AS \\"Identity Type 1\\", vcidentitydetails1 AS \\"Identity Detail 1\\", vcidentitytype2 AS \\"Identity Type 2\\", vcidentitydetails2 AS \\"Identity Detail 2\\", vcregisteredaddressgeolocation AS \\"Registered Address Geolocation\\" FROM masters.customers WHERE itenantid = :tenantid :AttribsForm AND dtentrydatetime BETWEEN :StartDate AND :EndDate ORDER BY icustomerid DESC LIMIT :Load ;",
        "Account": "SELECT iaccountid AS \\"Account ID\\", icustomerid AS \\"Customer ID\\", vcexternalaccountid AS \\"External Account ID\\", vcaccountname AS \\"Account Name\\", iaccounttypeid AS \\"Account Type\\", bverified AS \\"Verified\\",  dtonboardingdate AS \\"Onboarding Date\\", vcifsc AS \\"IFSC\\", vcaccount AS \\"Account Number\\", imcc AS \\"MCC\\", bmerchant AS \\"Merchant\\", irecordstatus AS \\"Record Status\\", dtentrydatetime AS \\"Entry Date Time\\", lastmodified AS \\"Last Modified\\" FROM masters.accounts WHERE itenantid = :tenantid :AttribsForm AND dtentrydatetime BETWEEN :StartDate AND :EndDate ORDER BY iaccountid DESC LIMIT :Load ;",
        "VPA": "SELECT ivpaid AS \\"VPA ID\\", iaccountid AS \\"Account ID\\", vcexternaladdressid AS \\"External VPA ID\\", vcaddress AS \\"VPA\\", vcvpaname AS \\"Customer Name\\", bverified AS \\"Verified\\", imcc AS \\"MCC\\", bmerchant AS \\"Merchant\\", irecordstatus AS \\"Record Status\\", dtentrydatetime AS \\"Entry Date Time\\", dtonboardingdate AS \\"Onboarding Date\\", iproductid AS \\"Product ID\\", dtexpirydate AS \\"Expires On\\", lastmodified AS \\"Last Modified On\\" FROM masters.vpa WHERE itenantid = :tenantid :AttribsForm AND dtentrydatetime BETWEEN :StartDate AND :EndDate ORDER BY ivpaid DESC LIMIT :Load ;"
    }
}
'::text WHERE
idashboardqueryid = 48 AND itenantid = 25;



UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
    "StartStage": {
      "EndStage": {
        "ClosedOn": "select TicketID.ticketid as \\"Case ID\\", pinst.start_time_ as \\"Case creation time\\", Alert.text_ as \\"Alert\\", cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''payerVPA''->>''externalId''  as \\"Payer\\", cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''payeeVPA''->>''externalId'' as \\"Payee\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''observations''->''vpa''->>''vcexternaladdressid'' else  cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''vpa''->>''vcexternaladdressid'' END  as \\"VPA\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''observations''->''account''->>''vcexternalaccountid'' else cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''account''->>''vcexternalaccountid'' END  as \\"Account\\", Amount.double_ / 100 as \\"Amount\\", oplogclaimstart.time_ as \\"Start stage\\", oplogclaimend.time_ as \\"End stage\\", CASE WHEN EXTRACT(EPOCH FROM (endstage.end_time_ - startstage.start_time_)) < 0 or EXTRACT(EPOCH FROM (endstage.end_time_ - startstage.start_time_)) is null THEN ''NA'' ELSE TO_CHAR( (EXTRACT(EPOCH FROM (endstage.end_time_ - startstage.start_time_)) || '' seconds'')::interval, ''HH24:MI:SS'' ) END as \\"Total time taken\\", case when assigneeuser.email_ is null then task.assignee_ else assigneeuser.email_ end as \\"Closed By\\", pinst.end_time_ as \\"Closed On\\" from camunda.act_hi_procinst pinst left join camunda.act_hi_taskinst task on task.id_ = ( select id_ from camunda.act_hi_taskinst where proc_inst_id_ = pinst.proc_inst_id_ and proc_def_key_ = pinst.proc_def_key_ order by end_time_ desc limit 1 ) left join camunda.act_hi_taskinst startstage on startstage.id_ = ( select id_ from camunda.act_hi_taskinst where proc_inst_id_ = pinst.proc_inst_id_ and proc_def_key_ = pinst.proc_def_key_ order by start_time_ asc limit 1 ) and startstage.proc_def_key_ = pinst.proc_def_key_ left join camunda.act_hi_taskinst endstage on endstage.id_ = ( select id_ from camunda.act_hi_taskinst where proc_inst_id_ = pinst.proc_inst_id_ and proc_def_key_ = pinst.proc_def_key_ order by start_time_ desc limit 1 ) left join ui.ticketidgenerator TicketID on TicketID.processinstanceid = pinst.proc_inst_id_ left join camunda.act_hi_varinst Alert on Alert.name_ =''Alert'' and Alert.var_type_ = ''string'' and Alert.proc_inst_id_ = pinst.proc_inst_id_ left join camunda.act_hi_varinst Amount on Amount.proc_inst_id_ = pinst.proc_inst_id_ and Amount.name_ =''TransactionAmount'' and Amount.var_type_ = ''double'' left join camunda.act_hi_detail oplogclaimstart on oplogclaimstart.id_ = (select id_ from camunda.act_hi_detail where proc_inst_id_ = pinst.proc_inst_id_ and name_ = ''userActivity'' and cast(text_ as jsonb)->>''action'' = ''Claim'' and cast(text_ as jsonb)->>''id'' = startstage.id_  order by time_ desc limit 1) and oplogclaimstart.name_ = ''userActivity'' and oplogclaimstart.proc_inst_id_ = pinst.proc_inst_id_ left join camunda.act_hi_detail oplogclaimend on oplogclaimend.id_ = (select id_ from camunda.act_hi_detail where proc_inst_id_ = pinst.proc_inst_id_ and name_ = ''userActivity'' and cast(text_ as jsonb)->>''action'' = ''Claim'' and cast(text_ as jsonb)->>''id'' = endstage.id_ order by time_ desc limit 1) and oplogclaimend.name_ = ''userActivity''  and oplogclaimend.proc_inst_id_ = pinst.proc_inst_id_ left join camunda.act_hi_varinst  Txn on Txn.proc_inst_id_ = pinst.proc_inst_id_ and Txn.name_ = ''Transaction'' and Txn.var_type_ = ''json'' left join camunda.act_ge_bytearray Txnorg on Txnorg.id_ = Txn.bytearray_id_ and Txnorg.name_ =  ''Transaction'' left join camunda.act_id_user assigneeuser on assigneeuser.id_ = task.assignee_ where cast(pinst.end_time_ as date) between cast(:StartDate as date) and cast(:EndDate as date) and pinst.proc_def_key_ = :CaseType and pinst.tenant_id_ = :tenantidstr and pinst.state_ =''COMPLETED'' limit :CountLimit",
        "CreatedOn": "select TicketID.ticketid as \\"Case ID\\", pinst.start_time_ as \\"Case creation time\\", Alert.text_ as \\"Alert\\", cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''payerVPA''->>''externalId''  as \\"Payer\\", cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''payerVPA''->>''externalId'' as \\"Payee\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''observations''->''vpa''->>''vcexternaladdressid'' else  cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''vpa''->>''vcexternaladdressid'' END  as \\"VPA\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''observations''->''account''->>''vcexternalaccountid'' else cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''account''->>''vcexternalaccountid'' END  as \\"Account\\", Amount.double_ / 100 as \\"Amount\\", oplogclaimstart.time_ as \\"Start stage\\", oplogclaimend.time_ as \\"End stage\\", CASE WHEN EXTRACT(EPOCH FROM (endstage.end_time_ - startstage.start_time_)) < 0 or EXTRACT(EPOCH FROM (endstage.end_time_ - startstage.start_time_)) is null THEN ''NA'' ELSE TO_CHAR( (EXTRACT(EPOCH FROM (endstage.end_time_ - startstage.start_time_)) || '' seconds'')::interval, ''HH24:MI:SS'' ) END as \\"Total time taken\\", case when assigneeuser.email_ is null then task.assignee_ else assigneeuser.email_ end as \\"Closed By\\", pinst.end_time_ as \\"Closed On\\" from camunda.act_hi_procinst pinst left join camunda.act_hi_taskinst task on task.id_ = ( select id_ from camunda.act_hi_taskinst where proc_inst_id_ = pinst.proc_inst_id_ and proc_def_key_ = pinst.proc_def_key_ order by end_time_ desc limit 1 ) left join camunda.act_hi_taskinst startstage on startstage.id_ = ( select id_ from camunda.act_hi_taskinst where proc_inst_id_ = pinst.proc_inst_id_ and proc_def_key_ = pinst.proc_def_key_ order by start_time_ asc limit 1 ) and startstage.proc_def_key_ = pinst.proc_def_key_ left join camunda.act_hi_taskinst endstage on endstage.id_ = ( select id_ from camunda.act_hi_taskinst where proc_inst_id_ = pinst.proc_inst_id_ and proc_def_key_ = pinst.proc_def_key_ order by start_time_ desc limit 1 ) left join ui.ticketidgenerator TicketID on TicketID.processinstanceid = pinst.proc_inst_id_ left join camunda.act_hi_varinst Alert on Alert.name_ =''Alert'' and Alert.var_type_ = ''string'' and Alert.proc_inst_id_ = pinst.proc_inst_id_ left join camunda.act_hi_varinst Amount on Amount.proc_inst_id_ = pinst.proc_inst_id_ and Amount.name_ =''TransactionAmount'' and Amount.var_type_ = ''double'' left join camunda.act_hi_detail oplogclaimstart on oplogclaimstart.id_ = (select id_ from camunda.act_hi_detail where proc_inst_id_ = pinst.proc_inst_id_ and name_ = ''userActivity'' and cast(text_ as jsonb)->>''action'' = ''Claim'' and cast(text_ as jsonb)->>''id'' = startstage.id_  order by time_ desc limit 1) and oplogclaimstart.name_ = ''userActivity'' and oplogclaimstart.proc_inst_id_ = pinst.proc_inst_id_ left join camunda.act_hi_detail oplogclaimend on oplogclaimend.id_ = (select id_ from camunda.act_hi_detail where proc_inst_id_ = pinst.proc_inst_id_ and name_ = ''userActivity'' and cast(text_ as jsonb)->>''action'' = ''Claim'' and cast(text_ as jsonb)->>''id'' = endstage.id_ order by time_ desc limit 1) and oplogclaimend.name_ = ''userActivity''  and oplogclaimend.proc_inst_id_ = pinst.proc_inst_id_ left join camunda.act_hi_varinst  Txn on Txn.proc_inst_id_ = pinst.proc_inst_id_ and Txn.name_ = ''Transaction'' and Txn.var_type_ = ''json'' left join camunda.act_ge_bytearray Txnorg on Txnorg.id_ = Txn.bytearray_id_ and Txnorg.name_ =  ''Transaction'' left join camunda.act_id_user assigneeuser on assigneeuser.id_ = task.assignee_ where cast(pinst.start_time_ as date) between cast(:StartDate as date) and cast(:EndDate as date) and pinst.proc_def_key_ = :CaseType and pinst.tenant_id_ = :tenantidstr and pinst.state_ =''COMPLETED'' limit :CountLimit"
      },
