        "ClosedOn": "select TicketID.ticketid as \\"Case ID\\", pinst.start_time_ as \\"Case creation time\\", Alert.text_ as \\"Alert\\", cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''payerVPA''->>''externalId''  as \\"Payer\\", cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''payeeVPA''->>''externalId'' as \\"Payee\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''observations''->''vpa''->>''vcexternaladdressid'' else  cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''vpa''->>''vcexternaladdressid'' END  as \\"VPA\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''observations''->''account''->>''vcexternalaccountid'' else cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''account''->>''vcexternalaccountid'' END  as \\"Account\\", Amount.double_ / 100 as \\"Amount\\", oplogclaimstart.time_ as \\"Start stage\\", oplogclaimend.time_ as \\"End stage\\", CASE WHEN EXTRACT(EPOCH FROM (endstage.end_time_ - startstage.start_time_)) < 0 or EXTRACT(EPOCH FROM (endstage.end_time_ - startstage.start_time_)) is null THEN ''NA'' ELSE TO_CHAR( (EXTRACT(EPOCH FROM (endstage.end_time_ - startstage.start_time_)) || '' seconds'')::interval, ''HH24:MI:SS'' ) END as \\"Total time taken\\", case when assigneeuser.email_ is null then task.assignee_ else assigneeuser.email_ end as \\"Closed By\\", pinst.end_time_ as \\"Closed On\\" from camunda.act_hi_procinst pinst left join camunda.act_hi_taskinst task on task.id_ = ( select id_ from camunda.act_hi_taskinst where proc_inst_id_ = pinst.proc_inst_id_ and proc_def_key_ = pinst.proc_def_key_ order by end_time_ desc limit 1 ) left join camunda.act_hi_taskinst startstage on startstage.id_ = ( select id_ from camunda.act_hi_taskinst wher