UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT d.vcdecisionname as "Decision Name", r.iruleid as "Rule ID", r.vcrulename as "Rule Name", makeruser.vcusername as "Maker User", r.dtentrystamp  as "Maker Time Stamp", r.vcremark as "Maker & Checker Remarks", checkeruser.vcusername as "Checker User", r.dtapproverstamp  as "Checker Time Stamp", case when r.vcaction = ''A'' then ''Add'' when r.vcaction = ''M'' then ''Modify'' when r.vcaction = ''X'' then ''Delete'' when r.vcaction = ''N'' then ''No Change'' end as "Action", iversion as "Rule Version", vclabel as "Rule Label", vcruledescription as "Rule Description", vcruledetail as "Rule Detail", vcruleparams as "Rule Params", vcruleorder as "Rule Order" FROM ui.rulesaudit r inner join ui.decisions d on r.idecisionid = d.idecisionid  left join ui.webuser makeruser on makeruser.iuserid = r.ientryuserid left join ui.webuser checkeruser on checkeruser.iuserid = r.iapproveruserid where d.itenantid = :tenantid and cast(r.dtentrystamp as date) between cast(:StartDate as date) and cast(:EndDate as date) limit 10000;
'::text WHERE
idashboardqueryid = 82 AND itenantid = 25;